starterProgram:
{
  "format": "plclab-lad",
  "version": 2,
  "name": "Main",
  "variables": [
    {
      "name": "StartPB",
      "type": "BOOL",
      "direction": "input",
      "comment": "Start button S1 (normally open)."
    },
    {
      "name": "StopPB",
      "type": "BOOL",
      "direction": "input",
      "comment": "Stop button S2 (normally closed: TRUE while not pressed)."
    },
    {
      "name": "LevelLow",
      "type": "BOOL",
      "direction": "input",
      "comment": "TRUE while the level is below the low switch (LSL-104 contact closes when dry)."
    },
    {
      "name": "LevelHigh",
      "type": "BOOL",
      "direction": "input",
      "comment": "TRUE while the level is at or above the high switch (LSH-103 contact closes when wet)."
    },
    {
      "name": "InletOpen",
      "type": "BOOL",
      "direction": "input",
      "comment": "Inlet valve fully-open limit switch."
    },
    {
      "name": "LevelRaw",
      "type": "INT",
      "direction": "input",
      "comment": "Raw analog value of LT-105 (scaling depends on the selected platform profile)."
    },
    {
      "name": "InletValve",
      "type": "BOOL",
      "direction": "output",
      "comment": "Inlet valve solenoid XV-101: TRUE opens the valve."
    },
    {
      "name": "DrainPump",
      "type": "BOOL",
      "direction": "output",
      "comment": "Drain pump P-102 contactor."
    }
  ],
  "rungs": [
    {
      "id": 1,
      "comment": "Start fills the tank until the high level switch.",
      "network": {
        "type": "series",
        "id": 2,
        "items": [
          {
            "type": "parallel",
            "id": 5,
            "branches": [
              {
                "type": "contact",
                "id": 3,
                "contact": "normallyOpen",
                "variable": "StartPB"
              },
              {
                "type": "contact",
                "id": 4,
                "contact": "normallyOpen",
                "variable": "InletValve"
              }
            ]
          },
          {
            "type": "contact",
            "id": 6,
            "contact": "normallyOpen",
            "variable": "StopPB"
          },
          {
            "type": "contact",
            "id": 7,
            "contact": "normallyClosed",
            "variable": "LevelHigh"
          }
        ]
      },
      "coils": [
        {
          "id": 8,
          "variable": "InletValve"
        }
      ]
    }
  ]
}
